    UPDATE public.calculators SET calc_category = 'process', description = $q$Cutting the part off its build plate through the support base with an oscillating power tool: the plate contact cut at the tool's cutting rate.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Plate Contact Area$q$, $q$Plate Contact Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Cutting Rate$q$, $q$Cutting Rate (mm²/s)$q$, $q$number$q$, $q$mm²/s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Plate Contact Area} / {Cutting Rate} * {Cycle Time Factor}$q$, 4, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Additive - Power tool base removal$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Additive Manufacturing$q$ AND operation IN ($q$Power Tool Base Removal$q$);
END
$calc$;

