-- Additive - Cleaning
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Additive - Cleaning$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Additive - Cleaning$q$, 'process', 'single', false, true, true, $q$Blasting the loose powder and residue off the part with compressed air: its surface at the machine's cleaning rate, never less than minCleaningTime. The export gives the rate (metalCleaningRate) without its unit; it is read as square metres a minute (unverified unit).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Blasting the loose powder and residue off the part with compressed air: its surface at the machine's cleaning rate, never less than minCleaningTime. The export gives the rate (metalCleaningRate) without its unit; it is read as square metres a minute (unverified unit).$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Surface Area$q$, $q$Surface Area (mm²)$q$, $q$number$q$, $q$mm²$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Cleaning Rate$q$, $q$Cleaning Rate (m²/min)$q$, $q$number$q$, $q$m²/min$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Minimum Time$q$, $q$Minimum Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$max({Minimum Time}, {Surface Area} / ({Cleaning Rate} * 1000000 / 60)) * {Cycle Time Factor}$q$, 5, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Additive - Cleaning$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Additive Manufacturing$q$ AND operation IN ($q$Cleaning$q$);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Additive - Parts per build$q$, 13, 0),
    ($q$Additive - Melt complexity$q$, 8, 0),
    ($q$Additive - Metal powder$q$, 10, 0),
    ($q$Additive - Polymer powder$q$, 14, 0),
    ($q$Additive - Resin and support material$q$, 10, 0),
    ($q$Additive - Build gas$q$, 5, 0),
    ($q$Additive - Metal sintering$q$, 25, 1),
    ($q$Additive - Laser sintering$q$, 17, 1),
    ($q$Additive - Material jetting$q$, 15, 1),
    ($q$Additive - Stereolithography$q$, 18, 1),
    ($q$Additive - Part curing$q$, 4, 1),
    ($q$Additive - Support breakoff$q$, 7, 1),
    ($q$Additive - Manual base removal$q$, 4, 1),
    ($q$Additive - Power tool base removal$q$, 4, 1),
    ($q$Additive - Powder loading$q$, 4, 1),
    ($q$Additive - Powder recovery$q$, 6, 1),
    ($q$Additive - Cleaning$q$, 5, 1)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Additive Manufacturing$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1073: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
